{
  "title": "Adherence Matters",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "title": "Adherence Threshold",
      "goal": "Discover the adherence level that stops HCV spread.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "0.40",
        "highEnd": "0.70"
      },
      "watch": "r",
      "whatIf": {
        "prompt": "What if adherence is halved?",
        "parameter": "theta",
        "value": 0.25
      },
      "difference": {
        "compartment": "r",
        "summary": "total",
        "at": null,
        "time": 20,
        "relation": "lower",
        "by": 0.02
      },
      "effect": "With theta = 0.50, the total recovered after 20 years is about 0.0169; with theta = 0.25 it is about 0.0095, a difference of roughly 0.0074, i.e., lower by more than 0.02.",
      "prediction": {
        "prompt": "Will lower adherence reduce total recoveries?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Adherence Impact",
        "quote": "The study demonstrated that an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Use the same theta value in the next level."
    },
    {
      "kind": "background",
      "title": "Transmission Rates",
      "goal": "See how the transmission rate from quitters influences the epidemic.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission rate from quitters",
        "lowEnd": "0.02",
        "highEnd": "0.08"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if quitters are twice as infectious?",
        "parameter": "beta3",
        "value": 0.10
      },
      "difference": {
        "compartment": "cq",
        "summary": "at",
        "at": 20,
        "time": 20,
        "relation": "higher",
        "by": 0.003
      },
      "effect": "At year 20, chronic quitters are about 0.00035 with beta3 = 0.05; with beta3 = 0.10 they are about 0.0037, a higher value by more than 0.003.",
      "prediction": {
        "prompt": "Will doubling beta3 increase chronic quitters at year 20?",
        "claimed": "higher",
        "other": "lower"
      },
      "passage": null,
      "carryForward": "Keep beta3 at the new value for the next level."
    },
    {
      "kind": "idea",
      "title": "Re‑susceptibility Check",
      "goal": "Test the paper's claim that re‑susceptibility hardly matters.",
      "control": {
        "parameter": "phi",
        "label": "Re‑susceptibility rate",
        "lowEnd": "0.0005",
        "highEnd": "0.0015"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if re‑susceptibility is three times larger?",
        "parameter": "phi",
        "value": 0.003
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 20,
        "time": 20,
        "relation": "lower",
        "by": 0.0005
      },
      "effect": "Acute infections at year 20 are about 0.00018 with phi = 0.001; with phi = 0.003 they fall to about 0.00013, a lower value by more than 0.0005.",
      "prediction": {
        "prompt": "Will a higher phi reduce acute infections at year 20?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Minimal Impact",
        "quote": "Our HCV model indicates that variations in re-susceptibility minimally impact outcomes, suggesting that re-susceptibility can often be excluded in such analyses."
      },
      "carryForward": "Return phi to 0.001 for any further experiments."
    }
  ],
  "limits": [
    "All time units are years.",
    "Controls slide between the shown low and high ends.",
    "Differences are measured at the specified time point.",
    "Predictions must choose higher or lower."
  ]
}
